values
  ('2026-10-15-gil-brothers-in-nyacoa-leadership', '2026-10-15', 'GIL brothers in NYACOA leadership', 'chapter', null, 'graphic', array['instagram', 'facebook', 'threads']::text[], 'needs-info', 'E-Board', 'Congratulate Bro. Lawrence Scott III, elected 1st Vice President, and Bro. Jessy Dwyer, elected Secretary, of the New York Association of Chapters of Alpha at the Oct. 2 to 3 state convention.', 'From the delegate''s report in the October chapter packet. Confirm titles with both brothers and get headshots before posting.', null, null, null, '2026-10-12T23:45:00Z'),
  ('2026-10-16-mlk-memorial-15-years', '2026-10-16', 'MLK Memorial: 15 years', 'alpha', null, 'carousel', array['instagram', 'facebook', 'threads']::text[], 'planned', 'Media', 'The Martin Luther King, Jr. Memorial was dedicated on Oct. 16, 2011. The idea began with brothers of Iota Upsilon Lambda Chapter in 1983, and Alpha led the effort to build it.', null, null, null, 'https://www.thememorialfoundation.org/mlk/memorial-history', '2026-10-12T23:45:00Z'),
  ('2026-10-19-liu-voter-registration-drive', '2026-10-19', 'LIU voter registration drive', 'chapter', 'vote', 'flyer', array['instagram', 'facebook', 'website', 'whatsapp']::text[], 'planned', 'Community Service', 'Promote the drives at LIU Brooklyn on Oct. 21 and 22, 12 to 2 p.m., with DX Alumni and the Brooklyn Voters Alliance. Invite students to register before the Oct. 24 deadline.', 'From the October chapter packet. Risk management approval was still pending; confirm before posting.', '2026-10-21', null, null, '2026-10-12T23:45:00Z'),
  ('2026-10-21-register-by-saturday', '2026-10-21', 'Register by Saturday', 'program', 'vote', 'graphic', array['instagram', 'facebook', 'threads']::text[], 'planned', 'Media', 'New York''s registration deadline for the Nov. 3 general election is Saturday, Oct. 24. Share the link to register and to check registration status.', null, null, null, 'https://ag.ny.gov/index.php/election-key-dates', '2026-10-12T23:45:00Z'),
  ('2026-10-22-making-strides-walk', '2026-10-22', 'Making Strides walk', 'chapter', null, 'graphic', array['instagram', 'facebook', 'whatsapp']::text[], 'planned', 'Community Service', 'Invite brothers and friends to walk with GIL at Making Strides Against Breast Cancer on Sunday, Oct. 25.', 'From the October chapter packet. Confirm the meeting point and team link.', '2026-10-25', null, null, '2026-10-12T23:45:00Z'),
  ('2026-10-23-early-voting-starts-tomorrow', '2026-10-23', 'Early voting starts tomorrow', 'program', 'vote', 'graphic', array['instagram', 'facebook', 'threads']::text[], 'planned', 'Media', 'Early voting in New York runs Saturday, Oct. 24 through Sunday, Nov. 1. Point followers to vote.nyc to find their site and hours.', null, null, null, 'https://ag.ny.gov/index.php/election-key-dates', '2026-10-12T23:45:00Z'),
  ('2026-10-26-brother-edward-w-brooke', '2026-10-26', 'Brother Edward W. Brooke', 'notable', null, 'graphic', array['instagram', 'facebook', 'threads']::text[], 'planned', 'Media', 'Born Oct. 26, 1919. In 1966 Brother Brooke became the first African American popularly elected to the U.S. Senate.', null, null, null, 'https://en.wikipedia.org/wiki/List_of_Alpha_Phi_Alpha_brothers', '2026-10-12T23:45:00Z'),
  ('2026-10-27-recap-voter-drive-and-making-strides', '2026-10-27', 'Recap: voter drive and Making Strides', 'chapter', 'vote', 'carousel', array['instagram', 'facebook', 'website']::text[], 'planned', 'Community Service', 'One carousel covering the LIU registration drives and the Making Strides walk. Lead with voters registered and brothers who walked.', 'Needs curated photos from Community Service by Oct. 26.', null, null, null, '2026-10-12T23:45:00Z'),
  ('2026-10-28-school-daze-tickets', '2026-10-28', 'School Daze tickets', 'chapter', null, 'flyer', array['instagram', 'facebook', 'website', 'whatsapp']::text[], 'planned', 'Social & Fundraising', 'Announce School Daze on Saturday, Nov. 21, the chapter''s signature party. Lead with the theme and the ticket link.', 'Confirm venue, time, and ticket price with Social & Fundraising.', '2026-11-21', 'https://www.zeffy.com/en-US/ticketing/school-daze-3', null, '2026-10-12T23:45:00Z'),
  ('2026-10-29-family-structures-and-generational-wealth', '2026-10-29', 'Family Structures and generational wealth', 'chapter', null, 'flyer', array['instagram', 'facebook', 'website', 'whatsapp']::text[], 'planned', 'Finance', 'Promote the Thursday, Nov. 12 program at 7 p.m. on family structures and practices that build and keep generational wealth, with Family Renaissance, Inc. Theme: Educate the Village, Educate the Community.', 'From the Finance report in the October packet. Confirm location and registration link.', '2026-11-12', null, null, '2026-10-12T23:45:00Z'),
  ('2026-10-30-early-voting-ends-sunday', '2026-10-30', 'Early voting ends Sunday', 'program', 'vote', 'story', array['instagram', 'facebook']::text[], 'planned', 'Media', 'Last weekend of early voting: Saturday and Sunday, Oct. 31 and Nov. 1. Election Day is Tuesday, Nov. 3.', null, null, null, 'https://ag.ny.gov/index.php/election-key-dates', '2026-10-12T23:45:00Z'),
  ('2026-11-03-election-day', '2026-11-03', 'Election Day', 'program', 'vote', 'graphic', array['instagram', 'facebook', 'threads']::text[], 'planned', 'Media', 'Today is Election Day in New York. Find your poll site at vote.nyc and bring someone with you. A voteless people is a hopeless people.', null, null, null, 'https://ag.ny.gov/index.php/election-key-dates', '2026-10-12T23:45:00Z'),
  ('2026-11-04-the-2027-28-fafsa-is-open', '2026-11-04', 'The 2027-28 FAFSA is open', 'program', 'college', 'carousel', array['instagram', 'facebook', 'threads', 'substack']::text[], 'planned', 'Education', 'The federal student aid form for 2027-28 opened in its earliest launch yet. Encourage seniors and families to file early and to ask Alpha Academy mentors for help.', null, null, null, 'https://kutv.com/news/nation-world/education-department-opens-2027-28-fafsa-early-marking-programs-earliest-launch', '2026-10-12T23:45:00Z'),
  ('2026-11-05-this-month-in-alpha-history-the-king-holiday', '2026-11-05', 'This month in Alpha history: the King holiday', 'series', null, 'carousel', array['instagram', 'facebook', 'threads']::text[], 'planned', 'Historian', 'Nov. 2, 1983: the bill creating the Martin Luther King, Jr. federal holiday became law. Pair it with the Historian''s highlight on GIL''s own Bro. Dr. Hobart S. Jarrett.', 'Coordinate with the Historian. The Jarrett highlight report is in progress per the October packet.', null, null, null, '2026-10-12T23:45:00Z'),
  ('2026-11-06-prematurity-awareness-month', '2026-11-06', 'Prematurity Awareness Month', 'program', 'project-alpha', 'graphic', array['instagram', 'facebook', 'threads']::text[], 'planned', 'Media', 'November is Prematurity Awareness Month. Alpha and March of Dimes have partnered since 1980 through Project Alpha. Share March of Dimes resources for healthy pregnancies.', null, null, null, 'https://www.marchofdimes.org/get-involved/partner/national-service-partners/alpha-phi-alpha-fraternity-inc', '2026-10-12T23:45:00Z'),
